  protected stateOf(item: SeatItem): SeatState {
    if (item.ids.some((id) => this.occupied().has(id))) return 'unavailable';
    if (this.booking.isSelected(item)) return 'selected';
    return item.accessible ? 'accessible' : 'available';
  }

